// Package placeholder holds a static "no cover available" image served in
// place of a book's real cover when that cover's file can't be found on
// disk (e.g. it lives outside the configured -files-root).
package placeholder

import "encoding/base64"

// MimeType is the media type of PNG.
const MimeType = "image/png"

// encodedPNG is a 600x900 solid gray image with thin white diagonal
// stripes, generated once and embedded here as a base64 string.
const encodedPNG = ``

// PNG is the decoded placeholder image bytes.
var PNG = mustDecode(encodedPNG)

func mustDecode(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}
